# FUNZIONI UTILITY - TO_EXCEL - PDF - BACKUP
# ==============================================================================
def to_excel(df, sheet_name="Foglio1"):
    output = io.BytesIO()
    try:
        with pd.ExcelWriter(output, engine='xlsxwriter') as writer:
            df.to_excel(writer, index=False, sheet_name=sheet_name)
            workbook = writer.book
            worksheet = writer.sheets[sheet_name]
            # Formato verde ANA per header
            header_format = workbook.add_format({
                'bold': True,
                'bg_color': '#1A5D1A',
                'font_color': 'white',
                'font_name': 'Times New Roman',
                'border': 1
            })
            for col_num, value in enumerate(df.columns.values):
                worksheet.write(0, col_num, value, header_format)
                worksheet.set_column(col_num, col_num, 20)
    except:
        with pd.ExcelWriter(output, engine='openpyxl') as writer:
            df.to_excel(writer, index=False, sheet_name=sheet_name)
    return output.getvalue()

def to_excel_openpyxl(df):
    output = io.BytesIO()
    with pd.ExcelWriter(output, engine='openpyxl') as writer:
        df.to_excel(writer, index=False)
    return output.getvalue()

def genera_pdf_filtrato(dati_filtrati, filtri_applicati):
    buffer = io.BytesIO()
    c = canvas.Canvas(buffer, pagesize=A4)
    width, height = A4
    # Header verde ANA
    c.setFillColor(HexColor("#1A5D1A"))
    c.rect(0, height-80, width, 80, fill=1, stroke=0)
    c.setFillColor(white)
    c.setFont("Times-Bold", 18)
    c.drawCentredString(width/2, height-40, "ANA VARESE - REPORT FILTRATO")
    c.setFont("Times-Bold", 10)
    c.drawCentredString(width/2, height-60, "Sezione Protezione Civile - Report Filtro PDF")
    c.setFillColor(black)
    y = height-110
    c.setFont("Times-Bold", 12)
    c.drawString(40, y, "Filtri applicati:")
    y -= 20
    c.setFont("Times-Roman", 10)
    for k,v in filtri_applicati.items():
        if v:
            c.drawString(50, y, f"{k}: {v}")
            y -= 14
            if y < 100:
                c.showPage()
                y = height-50
    y -= 20
    c.setFont("Times-Bold", 12)
    c.drawString(40, y, f"Totale volontari trovati: {len(dati_filtrati)}")
    c.showPage()
    # Tabella dati
    for idx, vol in enumerate(dati_filtrati):
        if idx % 15 == 0 and idx != 0:
            c.showPage()
            y = height-50
        else:
            if idx == 0:
                y = height-50
        c.setFont("Times-Roman", 9)
        riga = f"{vol.get('cognome','')} {vol.get('nome','')} - {vol.get('citta','')} - {vol.get('gruppo','')} - {vol.get('mansione','')}"
        c.drawString(40, y, riga[:110])
        y -= 14
    c.save()
    buffer.seek(0)
    return buffer.getvalue()

def genera_diploma_pdf(volontario, logo_ana_path=None, logo_pc_path=None, foto_path=None):
    # FIX 4: DIPLOMI 2 LOGHI NO BLU COMUNE, YF=H-12.5cm
    buffer = io.BytesIO()
    c = canvas.Canvas(buffer, pagesize=landscape(A4))
    w, h = landscape(A4)  # w=842, h=595 approx
    # Sfondo bianco
    c.setFillColor(white)
    c.rect(0,0,w,h, fill=1, stroke=0)
    # Bordo verde ANA
    c.setStrokeColor(HexColor("#1A5D1A"))
    c.setLineWidth(4)
    c.rect(10,10,w-20,h-20, fill=0, stroke=1)
    c.setLineWidth(1)
    c.rect(18,18,w-36,h-36, fill=0, stroke=1)
    # LOGO 1 ANA - alto sinistra
    c.setFillColor(HexColor("#1A5D1A"))
    c.setFont("Times-Bold", 14)
    c.drawString(40, h-60, "ANA")
    c.setFont("Times-Bold", 10)
    c.drawString(40, h-75, "Ass. Naz. Alpini")
    # LOGO 2 PROTEZIONE CIVILE - alto destra - NO BLU COMUNE
    c.setFillColor(HexColor("#1A5D1A"))
    c.setFont("Times-Bold", 14)
    c.drawRightString(w-40, h-60, "PROTEZIONE CIVILE")
    c.setFont("Times-Bold", 10)
    c.drawRightString(w-40, h-75, "ANA Varese")
    # Titolo diploma
    c.setFillColor(black)
    c.setFont("Times-Bold", 28)
    c.drawCentredString(w/2, h-120, "ATTESTATO DI PARTECIPAZIONE")
    c.setFont("Times-Bold", 16)
    c.drawCentredString(w/2, h-150, "Corso di Formazione Volontari")
    # Nome volontario
    c.setFont("Times-Bold", 22)
    nome_completo = f"{volontario.get('nome','')} {volontario.get('cognome','')}"
    c.drawCentredString(w/2, h-220, nome_completo)
    c.setFont("Times-Roman", 14)
    c.drawCentredString(w/2, h-250, f"Nato a {volontario.get('luogo','')} il {volontario.get('data_nascita','')}")
    c.drawCentredString(w/2, h-280, f"Gruppo {volontario.get('gruppo','')} - Mansione {volontario.get('mansione','')}")
    # Foto tessera YF = H - 12.5cm - FIX RICHIESTO EZIO
    # h e' altezza pagina landscape (595 pt). 12.5cm = 12.5*28.35 = 354.33 pt
    # yf = h - 12.5cm
    yf = h - (12.5 * cm)  # cm da reportlab = 28.35 pt, quindi 12.5cm = 354.375 pt
    foto_h = 4.5 * cm  # altezza foto tessera
    foto_w = 3.5 * cm  # larghezza foto tessera
    # Posizione foto: yf e' bordo superiore, quindi y = yf - foto_h
    c.setStrokeColor(HexColor("#1A5D1A"))
    c.rect(w-40-foto_w, yf-foto_h, foto_w, foto_h, fill=0, stroke=1)
    c.setFont("Times-Bold", 8)
    c.drawCentredString(w-40-foto_w/2, yf-foto_h-12, "FOTO")
    c.drawCentredString(w-40-foto_w/2, yf-foto_h-22, "TESSERA")
    c.drawCentredString(w-40-foto_w/2, yf-foto_h-32, f"YF=H-12.5cm")
    # Se foto_path esiste, disegna
    # if foto_path:
    #    c.drawImage(foto_path, w-40-foto_w, yf-foto_h, foto_w, foto_h)
    # Firme
    c.setFont("Times-Bold", 12)
    c.drawString(80, 80, "Il Presidente")
    c.drawString(80, 60, "ANA Varese")
    c.drawRightString(w-80, 80, "Il Coordinatore")
    c.drawRightString(w-80, 60, "Protezione Civile")
    c.setFont("Times-Roman", 10)
    c.drawCentredString(w/2, 40, f"Varese, {datetime.now().strftime('%d/%m/%Y')} - ID: {volontario.get('id','')}")
    c.save()
    buffer.seek(0)
    return buffer.getvalue()

