        f_zona = st.selectbox("15. Zona", ["", "Zona 1", "Zona 2", "Zona 3", "Zona 4"], key="filtro_zona")
        f_mansione = st.selectbox("16. Mansione", ["", "Volontario", "Caposquadra", "Coordinatore", "Autista", "Operatore Radio"], key="filtro_mansione")
        f_patente = st.text_input("17. Patente", key="filtro_patente")
