    with col4:
        st.markdown("<div style='background-color:#FFE0B2; padding:10px; font-family:Times New Roman; font-weight:bold; border:1px solid #1A5D1A;'>FILTRO 19-22</div>", unsafe_allow_html=True)
        f_corso_av = st.selectbox("19. Corso avanzato", ["", "SI", "NO"], key="filtro_corso_av")
        f_stato = st.selectbox("20. Stato volontario", ["", "Attivo", "Inattivo", "Sospeso"], key="filtro_stato")
        f_odv = st.text_input("21. ODV", key="filtro_odv")
        f_radio = st.text_input("22. Radio assegnata", key="filtro_radio")
        f_note = st.text_input("Filtro extra Note", key="filtro_note")
        f_tessera = st.text_input("Filtro extra Tessera", key="filtro_tessera")
    st.markdown("<br>", unsafe_allow_html=True)
    # Applica filtri
    if st.button("APPLICA FILTRI E GENERA ANTEPRIMA", key="applica_filtri", use_container_width=True):
        st.session_state.filtri_applicati = {
            "Nome": f_nome, "Cognome": f_cognome, "Data nascita": f_data_nascita, "Luogo": f_luogo,
            "Indirizzo": f_indirizzo, "CAP": f_cap, "Citta": f_citta, "Provincia": f_provincia,
            "Telefono": f_telefono, "Cellulare": f_cellulare, "Email": f_email, "Data iscrizione": f_data_iscrizione,
            "Scadenza": f_scadenza, "Gruppo": f_gruppo, "Zona": f_zona, "Mansione": f_mansione,
            "Patente": f_patente, "Corso base": f_corso_base, "Corso avanzato": f_corso_av,
            "Stato": f_stato, "ODV": f_odv, "Radio": f_radio
        }
        # Filtro logico
        risultati = []
        for v in st.session_state.volontari:
            match = True
            if f_nome and f_nome.lower() not in v.get('nome','').lower(): match=False
            if f_cognome and f_cognome.lower() not in v.get('cognome','').lower(): match=False
            if f_citta and f_citta.lower() not in v.get('citta','').lower(): match=False
            if f_gruppo and v.get('gruppo') != f_gruppo: match=False
            if f_mansione and v.get('mansione') != f_mansione: match=False
            if f_stato and v.get('stato') != f_stato: match=False
            if f_patente and f_patente.lower() not in v.get('patente','').lower(): match=False
            if f_corso_base and v.get('corso_base') != f_corso_base: match=False
            if match: risultati.append(v)
        st.session_state.risultati_filtro = risultati
        st.success(f"Trovati {len(risultati)} volontari con i filtri applicati")
    # Mostra risultati e download PDF
    if 'risultati_filtro' in st.session_state:
        risultati = st.session_state.risultati_filtro
        if risultati:
            df_ris = pd.DataFrame(risultati)
            st.dataframe(df_ris, use_container_width=True)
            st.markdown("<br>", unsafe_allow_html=True)
