def pagina_diplomi():
    st.markdown("""
    <div style='background-color:#1A5D1A; color:white; padding:15px; text-align:center; font-family:Times New Roman; font-weight:bold; font-size:22px;'>
    GENERAZIONE DIPLOMI - 2 LOGHI - YF=H-12.5cm
    </div>
    """, unsafe_allow_html=True)
    st.markdown("<br>", unsafe_allow_html=True)
    st.markdown("""
    <div style='background-color:#FFF9C4; border:2px solid #1A5D1A; padding:15px; font-family:Times New Roman; font-weight:bold; font-size:14px;'>
    FIX 4 APPLICATO: Diploma con 2 loghi (ANA e Protezione Civile), NO scritta blu COMUNE.<br>
    Foto tessera posizionata con formula YF = H - 12.5cm (12.5cm = 354.33 pt reportlab).<br>
    Layout pulito, Times New Roman grassetto, bordo verde ANA #1A5D1A.
    </div>
    """, unsafe_allow_html=True)
    st.markdown("<br>", unsafe_allow_html=True)
