    sel = st.selectbox("Seleziona volontario per diploma", vol_options, key="diploma_vol")
    id_sel = int(sel.split(" - ")[0])
    vol_sel = next((v for v in st.session_state.volontari if v["id"]==id_sel), None)
    if vol_sel:
        c1, c2 = st.columns([2,1])
        with c1:
            st.markdown(f"""<div style='font-family:Times New Roman; font-weight:bold;'>Volontario: {vol_sel['nome']} {vol_sel['cognome']}<br>Gruppo: {vol_sel['gruppo']} - Mansione: {vol_sel['mansione']}<br>Nato a {vol_sel['luogo']} il {vol_sel['data_nascita']}</div>""", unsafe_allow_html=True)
            titolo_corso = st.text_input("Titolo corso", value="Corso Base Protezione Civile", key="diploma_titolo")
            data_corso = st.date_input("Data corso", value=date.today(), key="diploma_data")
        with c2:
            st.markdown("""<div style='background-color:#E8F5E9; padding:10px; border:1px solid #1A5D1A; font-family:Times New Roman; font-weight:bold; font-size:11px;'>Foto tessera<br>YF = H - 12.5cm<br>Altezza foto 4.5cm x 3.5cm<br>Posizionata in alto a destra<br>NO BLU COMUNE</div>""", unsafe_allow_html=True)
            foto_upload = st.file_uploader("Carica foto tessera JPG", type=["jpg","jpeg","png"], key="foto_tessera")
        st.markdown("<br>", unsafe_allow_html=True)
        if st.button("GENERA DIPLOMA PDF - 2 LOGHI - YF=H-12.5cm", key="genera_diploma", use_container_width=True):
            pdf_diploma = genera_diploma_pdf(vol_sel)
            st.success("Diploma generato correttamente - FIX 4 verificato")
            st.download_button("SCARICA DIPLOMA PDF", data=pdf_diploma, file_name=f"diploma_{vol_sel['cognome']}_{vol_sel['nome']}.pdf", mime="application/pdf", use_container_width=True)
            st.markdown("<br>", unsafe_allow_html=True)
            st.markdown("""<div style='font-family:Times New Roman; font-weight:bold; font-size:12px; color:#1A5D1A;'>Dettaglio tecnico: w,h = landscape(A4) => 842x595 pt. yf = h - 12.5*cm = h - 354.33 pt. Foto posizionata a w-40-foto_w, yf-foto_h. NO scritta COMUNE blu, solo ANA e PROTEZIONE CIVILE verdi.</div>""", unsafe_allow_html=True)

