def valida_campo_05499(valore):
    # Validazione campo 05499 - solo testo ASCII - no emoji - Windows 7 compatibile
    if valore is None: return False
    if isinstance(valore, str):
        # Controllo ASCII only
        try:
            valore.encode('ascii')
            return len(valore.strip()) > 0
        except UnicodeEncodeError:
            return False
    return True

